import sys
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    if len(data) < 2:
        return

    s = data[1]
    dq = deque()
    rev = False
    o = ord('o')

    for k, c in enumerate(s, 1):
        # Add k to the end of the actual current prefix.
        if rev:
            dq.appendleft(k)
        else:
            dq.append(k)

        # If S_k is 'o', reverse the whole current prefix lazily.
        if c == o:
            rev = not rev

    if rev:
        dq.reverse()

    sys.stdout.write(' '.join(map(str, dq)))
    sys.stdout.write('\n')

if __name__ == "__main__":
    main()

