import sys

def permutation_rank(perm, n, fact):
    used = [False] * (n + 1)
    rank = 0

    for i, x in enumerate(perm):
        smaller_unused = 0
        for v in range(1, x):
            if not used[v]:
                smaller_unused += 1

        rank += smaller_unused * fact[n - 1 - i]
        used[x] = True

    return rank

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    n = data[0]
    p = data[1:1 + n]
    q = data[1 + n:1 + 2 * n]

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i

    rank_p = permutation_rank(p, n, fact)
    rank_q = permutation_rank(q, n, fact)

    ans = rank_q - rank_p - 1
    if ans < 0:
        ans = 0

    print(ans)

if __name__ == "__main__":
