from collections import deque

def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    try:
        N = next(it)
    except StopIteration:
        return

    M = next(it)
    S = next(it)
    T = next(it)

    adj = [[] for _ in range(N + 1)]
    INF = 10**9
    min_next = [INF] * (N + 1)

    for _ in range(M):
        a = next(it)
        b = next(it)
        adj[a].append(b)
        if b < min_next[a]:
            min_next[a] = b

    del it

    dist = [INF] * (N + 1)
    dist[S] = 0
    used = [False] * (N + 1)
    dq = deque([S])

    while dq:
        u = dq.popleft()
        if used[u]:
            continue

        used[u] = True
        if u == T:
            break

        du = dist[u]
        free_v = min_next[u]

        for v in adj[u]:
            if used[v]:
                continue

            if v == free_v:
                if du < dist[v]:
                    dist[v] = du
                    dq.appendleft(v)
            else:
                nd = du + 1
                if nd < dist[v]:
                    dist[v] = nd
                    dq.append(v)

    print(dist[T] if dist[T] != INF else -1)

